mapper.select:
        select
        userCollect.*,
        videos.video_name,
        videos.banner_img,
        videos.video_info,
        videoUser.nick_name,
        videoUser.head_img
        from likes userCollect
        left join videos videos on userCollect.video_id = videos.id
		left join video_user videoUser on userCollect.user_id = videoUser.id

            and userCollect.id = #{id}
            and userCollect.user_id = #{userId}
            and userCollect.video_id = #{videoId}
            and userCollect.create_time = #{createTime}
            and videos.video_name like concat('%',#{videoName},'%')
            and videos.banner_img = #{bannerImg}
            and videoUser.nick_name like concat('%',#{nickName},'%')
            and videoUser.head_img = #{headImg}

        order by create_time desc

            limit #{current},#{pageSize}

